import type { FrameworkInfo } from "../frameworks/detector";
import { isRequired } from "./validator";
import type { VariableInfo } from "./variables";

/** First line of every generated file. Used to recognise files envclinic may overwrite. */
export const GENERATED_MARKER = "// Generated by envclinic";

/**
 * Declared by @types/node or by frameworks themselves, so declaring them
 * again can cause conflicting-declaration errors. Skipped unless the schema
 * describes them.
 */
const RESERVED = new Set(["NODE_ENV", "TZ"]);

function isRequiredVariable(
  info: VariableInfo,
  hasSource: boolean,
  hasExample: boolean,
): boolean {
  if (info.schema) return isRequired(info.schema);
  if (hasSource && hasExample) return info.inSource && info.inExample;
  if (hasSource) return info.inSource;
  if (hasExample) return info.inExample;
  return false;
}

function tsType(info: VariableInfo): string {
  const field = info.schema;
  if (field?.type === "enum" && field.values && field.values.length > 0) {
    return field.values.map((value) => JSON.stringify(value)).join(" | ");
  }
  // Environment values are always strings at runtime, whatever the schema type.
  return "string";
}

function comment(info: VariableInfo, indent: string): string[] {
  const field = info.schema;
  if (field === undefined) return [];
  const parts: string[] = [];
  if (field.description) parts.push(field.description.replace(/\*\//g, "*\\/"));
  if (
    field.type === "number" ||
    field.type === "integer" ||
    field.type === "boolean"
  ) {
    parts.push(`Parse as ${field.type} (the value is a string at runtime).`);
  }
  return parts.length === 0 ? [] : [`${indent}/** ${parts.join(" ")} */`];
}

export interface TypeGenerationInput {
  variables: readonly VariableInfo[];
  framework: FrameworkInfo;
  hasSourceFiles: boolean;
  hasExample: boolean;
}

/**
 * Render TypeScript declarations for the project's environment variables.
 *
 * Output contains names and types only, never values. A variable is required
 * when the schema says so; without a schema it is required when it is
 * declared in the env file(s) and documented in the example file.
 */
export function renderTypes(input: TypeGenerationInput): string {
  const { framework } = input;
  const useImportMeta = framework.id === "vite" || framework.id === "astro";

  const processEnv: string[] = [];
  const importMetaEnv: string[] = [];

  for (const info of input.variables) {
    if (RESERVED.has(info.name) && !info.schema) continue;
    const required = isRequiredVariable(
      info,
      input.hasSourceFiles,
      input.hasExample,
    );
    const isPublic = framework.publicPrefixes.some((prefix) =>
      info.name.startsWith(prefix),
    );

    if (useImportMeta && isPublic) {
      importMetaEnv.push(
        ...comment(info, "  "),
        `  readonly ${info.name}${required ? "" : "?"}: ${tsType(info)};`,
      );
    } else {
      processEnv.push(
        ...comment(info, "    "),
        `    ${info.name}${required ? "" : "?"}: ${tsType(info)};`,
      );
    }
  }

  const out: string[] = [
    `${GENERATED_MARKER}. Do not edit by hand; run \`npx envclinic types\` to regenerate.`,
    "// These declarations improve editor autocomplete only. They do not validate values at runtime.",
  ];
  if (processEnv.length > 0) {
    out.push(
      "",
      "declare namespace NodeJS {",
      "  interface ProcessEnv {",
      ...processEnv,
      "  }",
      "}",
    );
  }
  if (importMetaEnv.length > 0) {
    out.push(
      "",
      "interface ImportMetaEnv {",
      ...importMetaEnv,
      "}",
      "",
      "interface ImportMeta {",
      "  readonly env: ImportMetaEnv;",
      "}",
    );
  }
  if (processEnv.length === 0 && importMetaEnv.length === 0) {
    out.push("", "export {};");
  }
  return out.join("\n") + "\n";
}
